package com.company.platform.integration.application;
import com.company.platform.integration.domain.*;import com.company.platform.integration.infrastructure.*;import java.sql.Timestamp;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class IntegrationPlatformService{private final JdbcTemplate jdbc;private final TenantContextProvider tenant;public IntegrationPlatformService(JdbcTemplate j,TenantContextProvider t){jdbc=j;tenant=t;}private UUID t(){return tenant.currentTenantId();}public Connector register(String n,String c,String p,String v,String d,String pr,String cfg){Connector x=Connector.register(t(),n,c,p,v,d,pr,cfg);save(x);audit(x.id(),null,"REGISTER","SUCCESS","connector registered",null);return x;}public Connector update(UUID id,String n,String cfg){Connector old=get(id);Connector x=new Connector(old.id(),old.tenantId(),n,old.code(),old.provider(),old.version(),old.direction(),old.protocol(),old.status(),cfg,old.createdAt(),Instant.now());save(x);audit(x.id(),null,"UPDATE","SUCCESS","connector updated",null);return x;}public Connector enable(UUID id){Connector x=get(id).enable();save(x);audit(x.id(),null,"ENABLE","SUCCESS","connector enabled",null);return x;}public Connector disable(UUID id){Connector x=get(id).disable();save(x);audit(x.id(),null,"DISABLE","SUCCESS","connector disabled",null);return x;}public Connector get(UUID id){return jdbc.query("SELECT * FROM integration_connectors WHERE tenant_id=? AND id=?",(r,n)->mapConnector(r),t(),id).stream().findFirst().orElseThrow(()->new NoSuchElementException("connector not found"));}public List<Connector> connectors(){return jdbc.query("SELECT * FROM integration_connectors WHERE tenant_id=? ORDER BY created_at DESC",(r,n)->mapConnector(r),t());}@Transactional public IntegrationJob execute(UUID connectorId,String type){Connector c=get(connectorId);if(!"ACTIVE".equals(c.status()))throw new IllegalStateException("connector is not active");IntegrationJob j=IntegrationJob.create(t(),connectorId,type).start();save(j);audit(c.id(),j.id(),"EXECUTE","SUCCESS","integration started",j.correlationId());return j;}public IntegrationJob retry(UUID id){IntegrationJob j=getJob(id);IntegrationJob x=new IntegrationJob(j.id(),j.tenantId(),j.connectorId(),j.executionType(),"RETRY_SCHEDULED",j.startedAt(),j.finishedAt(),j.correlationId(),j.retryCount()+1,j.createdAt());save(x);jdbc.update("INSERT INTO integration_retry_queue(id,tenant_id,job_id,payload,error,available_at,attempts,created_at) VALUES(?,?,?,?,?,?,?,?)",UUID.randomUUID(),t(),x.id(),"{}","manual retry",Timestamp.from(Instant.now().plusSeconds(Math.min(3600,1L<<Math.min(x.retryCount(),10)))),x.retryCount(),Timestamp.from(Instant.now()));audit(x.connectorId(),x.id(),"RETRY","SUCCESS","retry scheduled",x.correlationId());return x;}public IntegrationJob cancel(UUID id){IntegrationJob x=getJob(id).cancel();save(x);audit(x.connectorId(),x.id(),"CANCEL","SUCCESS","job cancelled",x.correlationId());return x;}public IntegrationJob getJob(UUID id){return jdbc.query("SELECT * FROM integration_jobs WHERE tenant_id=? AND id=?",(r,n)->mapJob(r),t(),id).stream().findFirst().orElseThrow(()->new NoSuchElementException("integration job not found"));}public List<IntegrationJob> jobs(){return jdbc.query("SELECT * FROM integration_jobs WHERE tenant_id=? ORDER BY created_at DESC",(r,n)->mapJob(r),t());}private void save(Connector x){jdbc.update("INSERT INTO integration_connectors(id,tenant_id,name,code,provider,version,direction,protocol,status,configuration,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=?,status=?,configuration=?,updated_at=?",x.id(),x.tenantId(),x.name(),x.code(),x.provider(),x.version(),x.direction(),x.protocol(),x.status(),x.configuration(),Timestamp.from(x.createdAt()),Timestamp.from(x.updatedAt()),x.name(),x.status(),x.configuration(),Timestamp.from(x.updatedAt()));}private void save(IntegrationJob x){jdbc.update("INSERT INTO integration_jobs(id,tenant_id,connector_id,execution_type,status,started_at,finished_at,correlation_id,retry_count,created_at) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET status=?,started_at=?,finished_at=?,retry_count=?",x.id(),x.tenantId(),x.connectorId(),x.executionType(),x.status(),ts(x.startedAt()),ts(x.finishedAt()),x.correlationId(),x.retryCount(),ts(x.createdAt()),x.status(),ts(x.startedAt()),ts(x.finishedAt()),x.retryCount());}private Timestamp ts(Instant x){return x==null?null:Timestamp.from(x);}private void audit(UUID c,UUID j,String a,String r,String m,UUID corr){jdbc.update("INSERT INTO integration_audit(id,tenant_id,connector_id,integration_job_id,action,result,message,correlation_id,created_at) VALUES(?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),t(),c,j,a,r,m,corr,Timestamp.from(Instant.now()));}private Connector mapConnector(java.sql.ResultSet r)throws java.sql.SQLException{return new Connector((UUID)r.getObject("id"),(UUID)r.getObject("tenant_id"),r.getString("name"),r.getString("code"),r.getString("provider"),r.getString("version"),r.getString("direction"),r.getString("protocol"),r.getString("status"),r.getString("configuration"),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant());}private IntegrationJob mapJob(java.sql.ResultSet r)throws java.sql.SQLException{return new IntegrationJob((UUID)r.getObject("id"),(UUID)r.getObject("tenant_id"),(UUID)r.getObject("connector_id"),r.getString("execution_type"),r.getString("status"),r.getTimestamp("started_at")==null?null:r.getTimestamp("started_at").toInstant(),r.getTimestamp("finished_at")==null?null:r.getTimestamp("finished_at").toInstant(),(UUID)r.getObject("correlation_id"),r.getInt("retry_count"),r.getTimestamp("created_at").toInstant());}}
